import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.BbQUUm7J.js";const p=JSON.parse('{"title":"Research Reports","description":"","frontmatter":{},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md","lastUpdated":1794861321000}'),o={name:"research/index.md"};function n(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="research-reports" tabindex="-1">Research Reports <a class="header-anchor" href="#research-reports" aria-label="Permalink to &quot;Research Reports&quot;">​</a></h1><p>The CLI&#39;s quantitative and architectural decisions are grounded in published research. These reports live in the repository and are cross-referenced by the <a href="/furlpay-cli/reference/honesty-matrix">Honesty Matrix</a>: any feature proposed by research but not yet implemented stays labeled as such.</p><h2 id="volume-index" tabindex="-1">Volume index <a class="header-anchor" href="#volume-index" aria-label="Permalink to &quot;Volume index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="https://github.com/FurlPay/furlpay-cli/blob/main/HFT_Execution_and_Alpha_Trading_Algorithms_Research_Report.md" target="_blank" rel="noreferrer">Institutional HFT Execution, Terminal UX &amp; Quantitative Alpha Algorithms (v1)</a></td><td>The engineering blueprint: dual-loop TUI architecture, sub-millisecond pipeline design, venue-specific acceleration (Hyperliquid WS POST, Jito bundles, Binance socket pinning, Stellar pre-auth), the first algorithm set (AS+OFI, VPIN gating, spatial/funding arb, adaptive micro-TWAP), and the pre-trade risk engine table.</td></tr><tr><td><a href="https://github.com/FurlPay/furlpay-cli/blob/main/HFT_V2_Advanced_Algorithms_Live_Research_Report.md" target="_blank" rel="noreferrer">HFT Alpha Catalog V2 — Live-Researched Algorithms &amp; Profitability Math</a></td><td>The 2025–2026 literature sweep: GLFT and RL market makers superseding Avellaneda-Stoikov, crypto-validated OFI/toxicity/quarter-hour signals, queue-position and Hawkes estimation, the adverse-selection objective function, a <strong>correction</strong> to the liquidation-sniping strategy (Hyperliquid backstop mechanics), where arbitrage edge survives in 2026, the maker&#39;s breakeven formulas, and a P0/P1/P2 roadmap mapped to CLI commands.</td></tr><tr><td><a href="https://github.com/FurlPay/furlpay-cli/blob/main/README.md#furlpay-cli--regulatory-licensing-and-compliance-research-report" target="_blank" rel="noreferrer">Regulatory, Licensing &amp; Compliance Research Report</a></td><td>The full multi-jurisdiction licensing matrix (US/EU/UK/SG), capital and surety-bond tables, and the developer compliance invariants. Condensed in <a href="/furlpay-cli/compliance/regulatory">Regulatory Overview</a>.</td></tr><tr><td><a href="https://github.com/FurlPay/furlpay-cli/blob/main/docs/USER_AUTHENTICATION_AND_TRADING_RESEARCH_REPORT.md" target="_blank" rel="noreferrer">User Authentication, Multi-Account Architecture &amp; Trading Execution Research Report</a></td><td>The dual-plane (identity vs. custody) architecture, RFC 8628 device login, custody topologies, and the security threat-model matrix.</td></tr><tr><td><a href="https://github.com/FurlPay/furlpay-cli/blob/main/AUDIT_REPORT.md" target="_blank" rel="noreferrer">Comprehensive Security Audit Report</a></td><td>The P1–P12 vulnerability matrix and remediations — all fixed as of the <code>fix(security)</code> commit series.</td></tr></tbody></table><h2 id="how-research-becomes-features" tabindex="-1">How research becomes features <a class="header-anchor" href="#how-research-becomes-features" aria-label="Permalink to &quot;How research becomes features&quot;">​</a></h2><ol><li><strong>Proposed</strong> — appears in a research volume with the model, math, and source literature.</li><li><strong>Implemented (offline)</strong> — the math ships behind the honesty labels (<code>microstructure analytics</code>, <code>vpin</code>, <code>quotes</code> compute over data you supply).</li><li><strong>Implemented (live)</strong> — wired to a real venue with the risk engine in front (<code>hyperliquid trade</code>, <code>earn hlp</code>).</li><li><strong>Never shipped as claimed</strong> — anything without a live venue or validated policy keeps its <code>SIMULATED</code> / <code>backtest-only</code> label permanently. A research report is never treated as proof of live profitability.</li></ol>',6)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
